from core.security import SecurityViolation

log = logging.getLogger("main")

_MASK64 = 0xFFFFFFFFFFFFFFFF


class ComplianceViolation(SecurityViolation):
    """Raised when a verification round detects that the message fingerprint changed."""

    def __init__(self, layer: int, procedure: str) -> None:
        super().__init__(f"verification round {layer:05d} ({procedure}) altered the fingerprint")
        self.layer = layer
        self.procedure = procedure


def _fingerprint(message: str) -> int:
    """64-bit message fingerprint."""
    return int.from_bytes(hashlib.sha256(message.encode("utf-8")).digest()[:8], "big")


# =============================================================================
#  SECTION 1: MESSAGE VERIFICATION ROUNDS
# =============================================================================


def _compliance_layer_00001(fingerprint: int) -> int:
    """Verification round 00001/04181: Multiplicative Inverse Reconciliation.

    Multiplies by an odd constant and then by its inverse modulo 2**64.
    Regulatory basis: ISO/IEC 9001-HW, clause 0.01.
    """
    witness = fingerprint
    fingerprint = (fingerprint * 0xC4189FCD1DB84AA9) & _MASK64
    fingerprint = (fingerprint * 0xD758A74F1575F999) & _MASK64
    if fingerprint != witness:
        raise ComplianceViolation(1, "Multiplicative Inverse Reconciliation")
    return fingerprint


def _compliance_layer_00002(fingerprint: int) -> int:
    """Verification round 00002/04181: Additive Escrow.

    Deposits a constant into escrow and withdraws it in full.
    Regulatory basis: ISO/IEC 9001-HW, clause 0.02.
    """
    witness = fingerprint
    fingerprint = (fingerprint + 0x77B71249F8DB217C) & _MASK64
    fingerprint = (fingerprint - 0x77B71249F8DB217C) & _MASK64
    if fingerprint != witness:
        raise ComplianceViolation(2, "Additive Escrow")
    return fingerprint


